// Parity: the TypeScript clustering must reproduce the untouched Python (`reduce.py`/`board.py`)
// exactly, on a Twitch-realistic corpus AND a 500-message slice of a real committed fixture.
// Golden vectors are generated by `scripts/gen_parity.py`. If this fails, the browser is no
// longer running the same algorithm the evaluation stands on.
import { describe, expect, it } from "vitest";
import parity from "../fixtures/parity.json";
import { canonical } from "../../src/cluster/canonical";
import { groupChat, groupedSummary } from "../../src/cluster/group";
import { pulse, questions } from "../../src/cluster/pulse";
import type { ChatEvent } from "../../src/cluster/types";

interface GroupCase {
  name: string;
  window: [number, number];
  events: ChatEvent[];
  groups: unknown[];
  summary: unknown;
  pulse: Record<string, unknown>;
  questions_fn: unknown;
}

const data = parity as unknown as {
  canonical: { in: string; out: string }[];
  groupCases: GroupCase[];
};

describe("canonical() parity with reduce.py", () => {
  for (const c of data.canonical) {
    it(`canonical(${JSON.stringify(c.in)}) === ${JSON.stringify(c.out)}`, () => {
      expect(canonical(c.in)).toBe(c.out);
    });
  }
});

describe("group_chat / grouped_summary / rail parity", () => {
  for (const c of data.groupCases) {
    describe(c.name, () => {
      it("group_chat matches", () => {
        expect(groupChat(c.events)).toEqual(c.groups);
      });

      it("grouped_summary matches", () => {
        expect(groupedSummary(c.events, groupChat(c.events))).toEqual(c.summary);
      });

      it("questions() matches", () => {
        expect(questions(c.events)).toEqual(c.questions_fn);
      });

      it("pulse (chat-only rail fields) matches", () => {
        const [start, end] = c.window;
        const p = pulse(c.events, start, end, []);
        // Compare only the fields the Python rail also produces for a chat-only window.
        const picked = {
          messages: p.messages,
          rate: p.rate,
          peak_burst: p.peak_burst,
          peak_per_second: p.peak_per_second,
          unique_chatters: p.unique_chatters,
          new_chatters: p.new_chatters,
          messages_per_chatter: p.messages_per_chatter,
          concentration: p.concentration,
          reaction_wave: p.reaction_wave,
          active_groups: p.active_groups,
          composition: p.composition,
          questions: p.questions,
        };
        expect(picked).toEqual(c.pulse);
      });
    });
  }
});
